class Solution {
    public:long long totalCost(vector<int>& costs,int k,int candidates){
        using Worker=pair<int,int>;
        priority_queue<Worker,vector<Worker>,greater<Worker>> leftHeap,rightHeap;
        int left=0,right=costs.size()-1;
        while(left<=right&&(int)leftHeap.size()<candidates){
            leftHeap.push({
                costs[left],left
            });
            ++left;
        }while(left<=right&&(int)rightHeap.size()<candidates){
            rightHeap.push({
                costs[right],right
            });
            --right;
        }
        long long answer=0;
        while(k--){
            bool takeLeft=rightHeap.empty()||(!leftHeap.empty()&&leftHeap.top()<=rightHeap.top());
            auto chosen=takeLeft?leftHeap.top():rightHeap.top();
            if(takeLeft)leftHeap.pop();
            else rightHeap.pop();
            answer+=chosen.first;
            if(left<=right){
                if(takeLeft){
                    leftHeap.push({
                        costs[left],left
                    });
                    ++left;
                }else{
                    rightHeap.push({
                        costs[right],right
                    });
                    --right;
                }
            }
        }
        return answer;
    }
};
